import de.backendlab.experiments.Experiments;import java.util.concurrent.*;
public class ExtendedChecks { public static void main(String[] args){var pool=Executors.newFixedThreadPool(32);try{for(String mode:new String[]{"atomic","lock"})if(!Boolean.TRUE.equals(Experiments.reserve(mode,100,200,pool).get("correct")))throw new AssertionError(mode);var a=Experiments.cpu(10000,100,1,pool);var b=Experiments.cpu(10000,100,4,pool);if(!a.get("checksum").equals(b.get("checksum")))throw new AssertionError("checksum");if(!Experiments.stampede(32,true,pool).get("loads").equals(1))throw new AssertionError("stampede");if((int)Experiments.pool(32,5,pool).get("peak")>5)throw new AssertionError("pool");System.out.println("PASS: atomic/lock reservation; sequential/parallel checksum; single-flight; pool bound");}finally{pool.shutdownNow();}}}
